    @Transactional(readOnly = true)
    public List<PersonFigures> personFigures(String sheetId, LocalDate asOf) {
        Rollup rollup = rollup(sheetId, asOf);
        Map<Long, List<String>> aliases = personService.aliases(sheetId, asOf);
